// Frontend mirrors backend entity shapes so future backend changes propagate
// via a simple type sync, not scattered refactors.

export type ScenarioCategory = string;

export const SUGGESTED_CATEGORIES: ScenarioCategory[] = ['happy_path', 'edge_case', 'out_of_scope', 'adversarial'];

export const TEST_RUN_STATUSES = ['pending', 'running', 'completed', 'failed', 'cancelled'] as const;
export type TestRunStatus = (typeof TEST_RUN_STATUSES)[number];

export const SCENARIO_RESULT_STATUSES = ['pass', 'partial', 'fail', 'error', 'timeout'] as const;
export type ScenarioResultStatus = (typeof SCENARIO_RESULT_STATUSES)[number];

/**
 * UI-only superset used for rendering in-progress scenarios before a result
 * row exists. The backend never returns 'pending' or 'running' on a scenario
 * result — those are synthesized client-side from the TestRun status.
 */
export type DisplayScenarioResultStatus = ScenarioResultStatus | 'pending' | 'running';

export const VERDICT_RESULTS = ['pass', 'partial', 'fail'] as const;
export type VerdictResult = (typeof VERDICT_RESULTS)[number];

export function isValidTestRunStatus(value: string): value is TestRunStatus {
  return (TEST_RUN_STATUSES as readonly string[]).includes(value);
}

export interface AgentCapability {
  blockId: string;
  agentName?: string;
  systemPrompt: string;
  sourceType: 'q-in-connect';
}

export interface CapabilityMap {
  agents: AgentCapability[];
}

export interface Flow {
  tenantId: string;
  flowId: string;
  flowName: string;
  phoneNumber: string;
  flowJson?: string;
  capabilityMap?: CapabilityMap;
  connectInstanceId?: string;
  createdAt: string;
  updatedAt: string;
}

export interface Scenario {
  tenantId: string;
  scenarioId: string;
  name: string;
  category: ScenarioCategory;
  callerPrompt: string;
  judgementPrompt: string;
  flowId?: string;
  createdBy?: string;
  createdAt: string;
}

export interface TranscriptTurn {
  speaker: 'caller' | 'agent';
  text: string;
  timestamp: number;
}

export interface FlaggedTurn {
  turnIndex: number;
  speakerText: string;
  issue: string;
}

export interface Verdict {
  result: VerdictResult;
  confidence: number;
  reasoning: string;
  flaggedTurns: FlaggedTurn[];
}

export interface ScenarioResult {
  runId: string;
  scenarioId: string;
  status: ScenarioResultStatus;
  transcript: TranscriptTurn[] | null;
  verdict: Verdict | null;
  startedAt?: string;
  completedAt?: string;
}

export interface TestRun {
  tenantId: string;
  runId: string;
  flowId: string;
  status: TestRunStatus;
  scenarioIds: string[];
  phoneNumber: string;
  totalScenarios: number;
  completedScenarios: number;
  passRate?: number;
  ecsTaskArn?: string;
  startedAt?: string;
  completedAt?: string;
  createdBy?: string;
  createdAt: string;
}

export interface CreateFlowInput {
  flowName: string;
  phoneNumber: string;
  flowJson?: string;
  capabilityMap?: CapabilityMap;
  connectInstanceId?: string;
}

export interface UpdateFlowInput {
  flowName?: string;
  phoneNumber?: string;
  flowJson?: string;
  capabilityMap?: CapabilityMap;
  connectInstanceId?: string;
}

export interface CreateScenarioInput {
  flowId?: string;
  name: string;
  category: ScenarioCategory;
  callerPrompt: string;
  judgementPrompt: string;
  createdBy?: string;
}

export interface UpdateScenarioInput {
  name?: string;
  category?: ScenarioCategory;
  callerPrompt?: string;
  judgementPrompt?: string;
}
